<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login();require_permission('category.manage');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='save'){$name=trim((string)($_POST['name']??''));$requested=trim((string)($_POST['slug']??''));$slug=substr(slugify($requested!==''?$requested:$name),0,120);$description=substr(trim((string)($_POST['description']??'')),0,500)?:null;$parent=(int)($_POST['parent_id']??0);$parent=$parent>0?$parent:null;$language=(string)($_POST['language']??'rw');$order=(int)($_POST['sort_order']??0);if(mb_strlen($name)<2||mb_strlen($name)>100||!in_array($language,['rw','en','fr'],true))throw new RuntimeException('Valid category name and language are required.');if($parent===$id&&$id>0)throw new RuntimeException('A category cannot be its own parent.');if($parent&&!query_one('SELECT id FROM categories WHERE id=? AND active=1',[$parent]))throw new RuntimeException('Parent category is unavailable.');$duplicate=query_one('SELECT id FROM categories WHERE slug=? AND id<>?',[$slug,$id]);if($duplicate)throw new RuntimeException('Category slug already exists.');
  if($id){db()->prepare('UPDATE categories SET name=?,slug=?,description=?,parent_id=?,language=?,sort_order=? WHERE id=?')->execute([$name,$slug,$description,$parent,$language,$order,$id]);}else{db()->prepare('INSERT INTO categories(name,slug,description,parent_id,language,sort_order,active) VALUES (?,?,?,?,?,?,1)')->execute([$name,$slug,$description,$parent,$language,$order]);$id=(int)db()->lastInsertId();}audit_log('category_save','category',$id,$slug);flash('Category saved and audited.');}
 elseif($action==='toggle'){$row=query_one('SELECT id,active FROM categories WHERE id=?',[$id]);if(!$row)throw new RuntimeException('Category missing.');if((int)$row['active']===1&&(int)(query_one('SELECT COUNT(*) n FROM articles WHERE category_id=?',[$id])['n']??0)>0)throw new RuntimeException('A category containing articles cannot be deactivated until content is reassigned.');$active=(int)$row['active']?0:1;db()->prepare('UPDATE categories SET active=? WHERE id=?')->execute([$active,$id]);audit_log($active?'category_activate':'category_deactivate','category',$id);flash('Category status updated.');}
 else throw new RuntimeException('Unknown category action.');header('Location: '.path('admin/categories.php'));exit;}catch(Throwable $e){$error=$e->getMessage();}}
$categories=query_all('SELECT c.*,p.name parent_name,(SELECT COUNT(*) FROM articles a WHERE a.category_id=c.id) article_count FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY c.sort_order,c.name');$parents=array_values(array_filter($categories,fn($c)=>(int)$c['active']===1&&empty($c['parent_id'])));
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories & Topics · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1200px;margin:auto"><p><a href="<?=e(path('admin/index.php'))?>">← Newsroom</a></p><div class="admin-section-title"><h1>Categories & topics<span class="brand-accent">.</span></h1></div><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice"><?=e($msg)?></div><?php endif;?><section class="setting-panel"><h2>Create category</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><label>NAME<input name="name" maxlength="100" required></label><label>SLUG (OPTIONAL)<input name="slug" maxlength="120"></label><label>DESCRIPTION<textarea name="description" maxlength="500"></textarea></label><label>PARENT<select name="parent_id"><option value="0">Top level</option><?php foreach($parents as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>LANGUAGE<select name="language"><option value="rw">Kinyarwanda</option><option value="en">English</option><option value="fr">Français</option></select></label><label>SORT ORDER<input type="number" name="sort_order" value="0"></label><button>SAVE CATEGORY →</button></form></section><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CATEGORY</th><th>PARENT / LANGUAGE</th><th>ARTICLES</th><th>STATUS</th><th>EDIT</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><b><?=e($c['name'])?></b><br><code><?=e($c['slug'])?></code></td><td><?=e($c['parent_name']??'Top level')?> · <?=e(strtoupper($c['language']))?></td><td><?=(int)$c['article_count']?></td><td><?=$c['active']?'Active':'Inactive'?></td><td><details><summary>Edit</summary><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$c['id']?>"><input name="name" value="<?=e($c['name'])?>" required><input name="slug" value="<?=e($c['slug'])?>" required><textarea name="description"><?=e($c['description']??'')?></textarea><select name="parent_id"><option value="0">Top level</option><?php foreach($parents as $p)if((int)$p['id']!==(int)$c['id']):?><option value="<?=$p['id']?>" <?=($c['parent_id']??0)==$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endif;?></select><select name="language"><?php foreach(['rw','en','fr'] as $lang):?><option value="<?=$lang?>" <?=$c['language']===$lang?'selected':''?>><?=e($lang)?></option><?php endforeach;?></select><input type="number" name="sort_order" value="<?=(int)$c['sort_order']?>"><button>SAVE</button></form></details><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$c['id']?>"><button><?=$c['active']?'DEACTIVATE':'ACTIVATE'?></button></form></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
